reg seen = 1'b0;
reg reset_edge = 1'b0;
reg tracking = 1'b1;
reg [6:0] wr = 0, dr = 0, hr = 0;
reg [3:0] lengths [0:63];
reg finished [0:63];
reg [63:0] bytes_q [0:63];
reg [3:0] out_pos = 0;
reg hold_m = 0, hold_h = 0;
reg [8:0] saved_m = 0;
reg [33:0] saved_h = 0;
reg [7:0] tail = 0;
integer i;
initial begin
    for (i=0; i<64; i=i+1) begin
        lengths[i] = 0;
        finished[i] = 0;
        bytes_q[i] = 0;
    end
end

wire [3:0] dl = lengths[dr[5:0]];
wire dc = finished[dr[5:0]];
wire [3:0] adjusted_dl = dl < 4 ? 4 : (dl > 8 ? 8 : dl);
wire byte_known = (out_pos < dl && out_pos < 8) ||
                         (dc && out_pos >= dl && out_pos < 4);
wire [7:0] expected_byte = out_pos < dl ?
                          (bytes_q[dr[5:0]] >> (out_pos*8)) : 8'b0;
wire last_known = dc || out_pos == 7 || out_pos < 7;
wire expected_last = dc ? (out_pos == adjusted_dl-1) : (out_pos == 7);
wire [3:0] hl = lengths[hr[5:0]];
wire [15:0] expected_hlen = hl < 4 ? 16'd4 : (hl > 8 ? 16'd8 : {12'd0,hl});
wire pending_data = (dr != wr) || (lengths[wr[5:0]] != 0);
wire pending_header = (hr != wr);

assign active[0] = seen && reset_edge;
assign ok[0] = !m_valid && !h_valid;
assign active[1] = seen && tracking && m_valid;
assign ok[1] = byte_known && m_data == expected_byte;
assign active[2] = seen && tracking && m_valid && byte_known && last_known;
assign ok[2] = m_last == expected_last;
assign active[3] = seen && tracking && h_valid;
assign ok[3] = hr != wr && finished[hr[5:0]] &&
               h_original_length == {12'd0,hl} &&
               h_length == expected_hlen && h_pad == (hl < 4) &&
               h_truncate == (hl > 8);
assign active[4] = seen && !reset_edge && (hold_m || hold_h);
assign ok[4] = (!hold_m || (m_valid && {m_last,m_data} == saved_m)) &&
               (!hold_h || (h_valid && {h_pad,h_truncate,h_length,h_original_length} == saved_h));
assign active[5] = seen && tracking && !rst && tail >= 32 &&
                   !s_valid && m_ready && h_ready;
assign ok[5] = !pending_data && !pending_header && !m_valid && !h_valid;

always @(posedge clk) begin
    seen <= 1'b1;
    reset_edge <= rst;
    if (rst) begin
        wr <= 0;
        dr <= 0;
        hr <= 0;
        out_pos <= 0;
        tracking <= 1'b1;
        hold_m <= 0;
        hold_h <= 0;
        tail <= 0;
        for (i=0; i<64; i=i+1) begin
            lengths[i] <= 0;
            finished[i] <= 0;
            bytes_q[i] <= 0;
        end
    end else begin
        hold_m <= m_valid && !m_ready;
        hold_h <= h_valid && !h_ready;
        saved_m <= {m_last,m_data};
        saved_h <= {h_pad,h_truncate,h_length,h_original_length};
        if (!s_valid && m_ready && h_ready) begin
            if (tail != 255) tail <= tail + 1'b1;
        end else tail <= 0;

        if (s_valid && s_ready && tracking) begin
            if (lengths[wr[5:0]] < 8)
                bytes_q[wr[5:0]][lengths[wr[5:0]]*8 +: 8] <= s_data;
            lengths[wr[5:0]] <= lengths[wr[5:0]] + 1'b1;
            if (s_last) begin
                finished[wr[5:0]] <= 1'b1;
                wr <= wr + 1'b1;
                lengths[(wr+1'b1) & 7'd63] <= 0;
                finished[(wr+1'b1) & 7'd63] <= 0;
                bytes_q[(wr+1'b1) & 7'd63] <= 0;
                if ((wr-dr == 7'd62) || (wr-hr == 7'd62)) tracking <= 1'b0;
            end
        end
        if (m_valid && m_ready && tracking) begin
            if (m_last) begin
                dr <= dr + 1'b1;
                out_pos <= 0;
            end else if (out_pos != 15) out_pos <= out_pos + 1'b1;
        end
        if (h_valid && h_ready && tracking) hr <= hr + 1'b1;
    end
end

reg seen = 1'b0;
reg reset_edge = 1'b0;
reg tracked = 1'b1;
reg [7:0] bytes_q [0:255];
reg lasts_q [0:255];
reg [3:0] lengths_q [0:127];
reg [7:0] bw = 0, br = 0;
reg [6:0] hw = 0, hr = 0;
reg [8:0] bc = 0;
reg [7:0] hc = 0;
reg [3:0] input_pos = 0;
reg ms = 0, hs = 0;
reg [8:0] held_m = 0;
reg [33:0] held_h = 0;
integer added;
integer k;
integer idx;
wire take_s = s_valid && s_ready && !rst;
wire take_m = m_valid && m_ready && !rst;
wire take_h = h_valid && h_ready && !rst;
wire enabled = seen && tracked;
wire [3:0] expected_original = lengths_q[hr];
wire [15:0] expected_length = expected_original < 4 ? 16'd4 : (expected_original > 8 ? 16'd8 : {12'd0,expected_original});

// Queues describe accepted transactions, not a timing model of the DUT.
assign active[0] = seen && reset_edge;
assign ok[0] = !m_valid && !h_valid;
assign active[1] = enabled && m_valid;
assign ok[1] = (bc != 0) && (m_data == bytes_q[br]);
assign active[2] = enabled && m_valid;
assign ok[2] = (bc != 0) && (m_last == lasts_q[br]);
assign active[3] = enabled && h_valid;
assign ok[3] = (hc != 0) &&
    (h_original_length == {12'd0,expected_original}) &&
    (h_length == expected_length) &&
    (h_pad == (expected_original < 4)) &&
    (h_truncate == (expected_original > 8));
assign active[4] = seen && ms && !reset_edge;
assign ok[4] = m_valid && ({m_data,m_last} == held_m);
assign active[5] = seen && hs && !reset_edge;
assign ok[5] = h_valid &&
    ({h_pad,h_truncate,h_length,h_original_length} == held_h);

always @(posedge clk) begin
    seen <= 1'b1;
    reset_edge <= rst;
    ms <= !rst && m_valid && !m_ready;
    hs <= !rst && h_valid && !h_ready;
    held_m <= {m_data,m_last};
    held_h <= {h_pad,h_truncate,h_length,h_original_length};
    if (rst) begin
        bw <= 0;
        br <= 0;
        hw <= 0;
        hr <= 0;
        bc <= 0;
        hc <= 0;
        input_pos <= 0;
        tracked <= 1'b1;
    end else if (tracked) begin
        added = 0;
        if (take_s) begin
            if (input_pos < 8) begin
                bytes_q[bw] <= s_data;
                lasts_q[bw] <= (input_pos == 7) || (s_last && input_pos >= 3);
                added = 1;
            end
            if (s_last && input_pos < 3) begin
                for (k = 1; k <= 3; k = k+1) begin
                    if (k <= 3-input_pos) begin
                        idx = (bw+k) & 255;
                        bytes_q[idx] <= 8'd0;
                        lasts_q[idx] <= (k == 3-input_pos);
                    end
                end
                added = 4-input_pos;
            end
            if (s_last) begin
                lengths_q[hw] <= input_pos+1'b1;
                hw <= hw+1'b1;
                input_pos <= 0;
            end else begin
                input_pos <= input_pos+1'b1;
            end
        end
        bw <= bw+added;
        if (take_m && bc != 0) br <= br+1'b1;
        bc <= bc+added-((take_m && bc != 0) ? 1 : 0);
        if (take_h && hc != 0) hr <= hr+1'b1;
        case ({(take_s && s_last),(take_h && hc != 0)})
            2'b10: hc <= hc+1'b1;
            2'b01: hc <= hc-1'b1;
            default: hc <= hc;
        endcase
        // If the passive observation budget is exhausted, stop interpreting
        // overwritten entries; reset starts a fresh, fully tracked epoch.
        if (bc+added-((take_m && bc != 0) ? 1 : 0) > 256)
            tracked <= 1'b0;
        if (take_s && s_last && hc == 128 && !(take_h && hc != 0))
            tracked <= 1'b0;
    end
end

reg started = 1'b0;
reg reset_edge = 1'b0;
reg [5:0] bad = 6'b0;
reg [7:0] wr_seq = 0, data_seq = 0, hdr_seq = 0;
reg [3:0] in_len = 0;
reg [3:0] data_pos = 0;
reg [63:0] frame_bytes [0:63];
reg [3:0] frame_len [0:63];
reg tracking = 1'b1;
reg m_hold = 0, h_hold = 0;
reg [7:0] held_data = 0;
reg held_last = 0;
reg [33:0] held_header = 0;
reg [5:0] enable_check, pass_check;
reg data_exists, data_complete, byte_known;
reg [3:0] known_len, adjusted_len;
reg [7:0] expected_byte;
reg expected_last;
reg [3:0] status_len, status_adjusted;
integer k;
initial begin
    for (k=0; k<64; k=k+1) begin
        frame_bytes[k] = 0;
        frame_len[k] = 0;
    end
end

always @* begin
    data_complete = (data_seq != wr_seq);
    data_exists = data_complete || (in_len != 0);
    known_len = data_complete ? frame_len[data_seq[5:0]] : in_len;
    adjusted_len = known_len < 4 ? 4 : (known_len > 8 ? 8 : known_len);
    byte_known = data_exists && ((data_pos < known_len && data_pos < 8) ||
                  (data_complete && data_pos < adjusted_len));
    expected_byte = 0;
    if (data_pos < known_len && data_pos < 8)
        expected_byte = frame_bytes[data_seq[5:0]][data_pos*8 +: 8];
    expected_last = data_complete ? (data_pos == adjusted_len-1) : (data_pos == 7);
    status_len = frame_len[hdr_seq[5:0]];
    status_adjusted = status_len < 4 ? 4 : (status_len > 8 ? 8 : status_len);

    enable_check = 0;
    pass_check = 6'b111111;
    enable_check[0] = started && reset_edge;
    pass_check[0] = !m_valid && !h_valid && !s_ready;

    enable_check[1] = started && !reset_edge && tracking && m_valid;
    pass_check[1] = byte_known && (m_data == expected_byte);
    enable_check[2] = started && !reset_edge && tracking && m_valid;
    pass_check[2] = byte_known && (m_last == expected_last);

    enable_check[3] = started && !reset_edge && tracking && h_valid;
    pass_check[3] = (hdr_seq != wr_seq) &&
                    (h_original_length == {12'b0,status_len}) &&
                    (h_length == {12'b0,status_adjusted}) &&
                    (h_pad == (status_len < 4)) &&
                    (h_truncate == (status_len > 8));

    enable_check[4] = started && !reset_edge && m_hold;
    pass_check[4] = m_valid && (m_data == held_data) && (m_last == held_last);
    enable_check[5] = started && !reset_edge && h_hold;
    pass_check[5] = h_valid &&
        ({h_pad,h_truncate,h_length,h_original_length} == held_header);
end
assign active = enable_check | bad;
assign ok = pass_check & ~bad;

always @(posedge clk) begin
    bad <= bad | (enable_check & ~pass_check);
    reset_edge <= rst;
    if (rst) begin
        started <= 1'b1;
        wr_seq <= 0;
        data_seq <= 0;
        hdr_seq <= 0;
        in_len <= 0;
        data_pos <= 0;
        tracking <= 1'b1;
        m_hold <= 0;
        h_hold <= 0;
    end else begin
        m_hold <= m_valid && !m_ready;
        h_hold <= h_valid && !h_ready;
        held_data <= m_data;
        held_last <= m_last;
        held_header <= {h_pad,h_truncate,h_length,h_original_length};
        if (started && tracking) begin
            if (s_valid && s_ready) begin
                if (in_len < 8)
                    frame_bytes[wr_seq[5:0]][in_len*8 +: 8] <= s_data;
                frame_len[wr_seq[5:0]] <= in_len + 1'b1;
                if (s_last) begin
                    wr_seq <= wr_seq + 1'b1;
                    in_len <= 0;
                    if (((wr_seq + 8'd1 - data_seq) >= 64) ||
                        ((wr_seq + 8'd1 - hdr_seq) >= 64))
                        tracking <= 1'b0;
                end else begin
                    in_len <= in_len + 1'b1;
                end
            end
            if (m_valid && m_ready && byte_known) begin
                if (expected_last) begin
                    data_seq <= data_seq + 1'b1;
                    data_pos <= 0;
                end else begin
                    data_pos <= data_pos + 1'b1;
                end
            end
            if (h_valid && h_ready && hdr_seq != wr_seq)
                hdr_seq <= hdr_seq + 1'b1;
        end
    end
end

reg seen = 1'b0;
reg reset_edge = 1'b0;
reg hold_m = 1'b0, hold_h = 1'b0;
reg [8:0] saved_m = 9'd0;
reg [33:0] saved_h = 34'd0;

// Independent consumers of a bounded accepted-input history.
reg [63:0] bytes_q [0:63];
reg [3:0] length_q [0:63];
reg complete_q [0:63];
reg [7:0] input_seq = 8'd0;
reg [7:0] data_seq = 8'd0;
reg [7:0] header_seq = 8'd0;
reg [3:0] input_length = 4'd0;
reg [3:0] data_position = 4'd0;
reg tracking = 1'b1;
wire [7:0] data_distance = input_seq - data_seq;
wire [7:0] header_distance = input_seq - header_seq;
wire data_exists = (data_distance != 0) || (input_length != 0);
wire header_exists = (header_distance != 0);
wire [3:0] dl = length_q[data_seq[5:0]];
wire dc = (data_distance != 0) && complete_q[data_seq[5:0]];
wire [3:0] adjusted_dl = dl < 4 ? 4 : (dl > 8 ? 8 : dl);
wire [3:0] hl = length_q[header_seq[5:0]];
wire [15:0] adjusted_hl = hl < 4 ? 16'd4 : (hl > 8 ? 16'd8 : {12'd0,hl});
wire byte_known = data_exists && (data_position < 8) &&
    ((data_position < dl) || (dc && data_position < adjusted_dl));
reg [7:0] expected_byte;
always @* begin
    expected_byte = 8'd0;
    if (data_position < dl && data_position < 8)
        expected_byte = bytes_q[data_seq[5:0]][data_position*8 +: 8];
end
wire last_known = byte_known && (dc || data_position == 7 || data_position + 1 < dl);
wire expected_last = (data_position == 7) || (dc && data_position + 1 == adjusted_dl);

assign active[0] = seen && reset_edge;
assign ok[0] = !m_valid && !h_valid;
assign active[1] = seen && !reset_edge && hold_m;
assign ok[1] = m_valid && ({m_last,m_data} == saved_m);
assign active[2] = seen && !reset_edge && hold_h;
assign ok[2] = h_valid && ({h_pad,h_truncate,h_length,h_original_length} == saved_h);
assign active[3] = seen && !reset_edge && tracking && m_valid;
assign ok[3] = byte_known && m_data == expected_byte;
assign active[4] = seen && !reset_edge && tracking && h_valid;
assign ok[4] = header_exists && complete_q[header_seq[5:0]] &&
    h_original_length == {12'd0,hl} && h_length == adjusted_hl &&
    h_pad == (hl < 4) && h_truncate == (hl > 8);
assign active[5] = seen && !reset_edge && tracking && m_valid;
assign ok[5] = byte_known && (!last_known ? !m_last : m_last == expected_last);

always @(posedge clk) begin
    seen <= 1'b1;
    reset_edge <= rst;
    hold_m <= !rst && m_valid && !m_ready;
    hold_h <= !rst && h_valid && !h_ready;
    saved_m <= {m_last,m_data};
    saved_h <= {h_pad,h_truncate,h_length,h_original_length};
    if (rst) begin
        input_seq <= 0;
        data_seq <= 0;
        header_seq <= 0;
        input_length <= 0;
        data_position <= 0;
        tracking <= 1'b1;
    end else if (tracking) begin
        // Stop rather than alias history if the monitor's capacity is exceeded.
        if (data_distance >= 63 || header_distance >= 63)
            tracking <= 1'b0;
        if (s_valid && s_ready) begin
            if (input_length < 8)
                bytes_q[input_seq[5:0]][input_length*8 +: 8] <= s_data;
            length_q[input_seq[5:0]] <= input_length + 1'b1;
            complete_q[input_seq[5:0]] <= s_last;
            if (s_last) begin
                input_seq <= input_seq + 1'b1;
                input_length <= 0;
            end else begin
                input_length <= input_length + 1'b1;
            end
        end
        if (m_valid && m_ready && byte_known) begin
            if (expected_last && last_known) begin
                data_seq <= data_seq + 1'b1;
                data_position <= 0;
            end else begin
                data_position <= data_position + 1'b1;
            end
        end
        if (h_valid && h_ready && header_exists)
            header_seq <= header_seq + 1'b1;
    end
end

reg seen = 1'b0;
reg past_reset = 1'b0;
reg hold_m = 1'b0, hold_h = 1'b0;
reg [8:0] saved_m = 0;
reg [33:0] saved_h = 0;
reg tracking = 1'b1;
reg [63:0] bytes_q [0:63];
reg [3:0] lengths [0:63];
reg complete_q [0:63];
reg live_m [0:63];
reg live_h [0:63];
reg [5:0] wr = 0, rd_m = 0, rd_h = 0;
reg [3:0] in_pos = 0, out_pos = 0;
reg [7:0] quiet = 0;
integer i;
reg justified;
reg expected_last;
reg [7:0] expected_byte;
reg [3:0] adjusted_m, adjusted_h;
reg drained;
initial begin
    for (i=0; i<64; i=i+1) begin
        bytes_q[i] = 0;
        lengths[i] = 0;
        complete_q[i] = 0;
        live_m[i] = 0;
        live_h[i] = 0;
    end
end

always @* begin
    adjusted_m = lengths[rd_m];
    if (lengths[rd_m] < 4) adjusted_m = 4;
    else if (lengths[rd_m] > 8) adjusted_m = 8;
    adjusted_h = lengths[rd_h];
    if (lengths[rd_h] < 4) adjusted_h = 4;
    else if (lengths[rd_h] > 8) adjusted_h = 8;
    justified = 1'b0;
    expected_byte = 0;
    expected_last = 1'b0;
    if (live_m[rd_m] && out_pos < 8) begin
        if (out_pos < lengths[rd_m]) begin
            justified = 1'b1;
            expected_byte = bytes_q[rd_m][out_pos*8 +: 8];
        end else if (complete_q[rd_m] && out_pos < adjusted_m) begin
            justified = 1'b1;
            expected_byte = 0;
        end
        if (complete_q[rd_m]) begin
            if (out_pos >= adjusted_m) justified = 1'b0;
            expected_last = (out_pos == adjusted_m-1);
        end else begin
            expected_last = (out_pos == 7);
        end
    end
    drained = (in_pos == 0);
    for (integer k=0; k<64; k=k+1)
        if (live_m[k] || live_h[k]) drained = 1'b0;
end

assign active[0] = seen && (past_reset || (tracking && quiet == 128));
assign ok[0] = past_reset ? (!m_valid && !h_valid && !s_ready) :
                            (drained && !m_valid && !h_valid);
assign active[1] = seen && hold_m;
assign ok[1] = m_valid && ({m_last,m_data} == saved_m);
assign active[2] = seen && hold_h;
assign ok[2] = h_valid && ({h_pad,h_truncate,h_length,h_original_length} == saved_h);
assign active[3] = seen && tracking && !past_reset && m_valid;
assign ok[3] = justified && (m_data == expected_byte);
assign active[4] = seen && tracking && !past_reset && m_valid;
assign ok[4] = justified && (m_last == expected_last);
assign active[5] = seen && tracking && !past_reset && h_valid;
assign ok[5] = live_h[rd_h] && complete_q[rd_h] &&
               (h_original_length == {12'b0,lengths[rd_h]}) &&
               (h_length == {12'b0,adjusted_h}) &&
               (h_pad == (lengths[rd_h] < 4)) &&
               (h_truncate == (lengths[rd_h] > 8));

always @(posedge clk) begin
    seen <= 1'b1;
    past_reset <= rst;
    hold_m <= !rst && m_valid && !m_ready;
    hold_h <= !rst && h_valid && !h_ready;
    saved_m <= {m_last,m_data};
    saved_h <= {h_pad,h_truncate,h_length,h_original_length};
    if (rst) begin
        tracking <= 1'b1;
        wr <= 0;
        rd_m <= 0;
        rd_h <= 0;
        in_pos <= 0;
        out_pos <= 0;
        quiet <= 0;
        for (integer j=0; j<64; j=j+1) begin
            lengths[j] <= 0;
            complete_q[j] <= 0;
            live_m[j] <= 0;
            live_h[j] <= 0;
        end
    end else begin
        if (!s_valid && m_ready && h_ready) begin
            if (quiet < 128) quiet <= quiet + 1'b1;
        end else quiet <= 0;
        if (tracking) begin
            if (m_valid && m_ready) begin
                if (m_last) begin
                    live_m[rd_m] <= 0;
                    rd_m <= rd_m + 1'b1;
                    out_pos <= 0;
                end else if (out_pos < 15) out_pos <= out_pos + 1'b1;
            end
            if (h_valid && h_ready) begin
                live_h[rd_h] <= 0;
                rd_h <= rd_h + 1'b1;
            end
            if (s_valid && s_ready) begin
                if (in_pos == 0) begin
                    if (live_m[wr] || live_h[wr]) tracking <= 0;
                    live_m[wr] <= 1;
                    live_h[wr] <= 1;
                    complete_q[wr] <= 0;
                end
                if (in_pos < 8) bytes_q[wr][in_pos*8 +: 8] <= s_data;
                lengths[wr] <= in_pos + 1'b1;
                if (s_last) begin
                    complete_q[wr] <= 1;
                    wr <= wr + 1'b1;
                    in_pos <= 0;
                end else if (in_pos < 14) in_pos <= in_pos + 1'b1;
            end
        end
    end
end

reg seen = 1'b0;
reg reset_edge = 1'b0;
reg epoch = 1'b0;
reg tracking = 1'b1;
reg [15:0] wr_frame = 0, data_frame = 0, hdr_frame = 0;
reg [3:0] input_length = 0;
reg [3:0] data_offset = 0;
reg [63:0] frame_bytes [0:63];
reg [3:0] frame_length [0:63];
reg data_hold = 0, hdr_hold = 0;
reg [8:0] held_data = 0;
reg [33:0] held_header = 0;
wire [33:0] header_now = {h_pad,h_truncate,h_length,h_original_length};
wire input_fire = s_valid && s_ready && !rst;
wire data_fire = m_valid && m_ready && !rst;
wire hdr_fire = h_valid && h_ready && !rst;
wire completed_data_frame = (data_frame != wr_frame);
wire data_available = completed_data_frame || (input_length != 0);
wire [3:0] known_length = completed_data_frame ? frame_length[data_frame[5:0]] : input_length;
wire [3:0] adjusted_length = known_length < 4 ? 4 : (known_length > 8 ? 8 : known_length);
wire byte_justified = data_available && (data_offset < 8) &&
    ((data_offset < known_length) || (completed_data_frame && data_offset < 4));
wire [7:0] expected_byte = data_offset < known_length ?
    (frame_bytes[data_frame[5:0]] >> (data_offset*8)) : 8'd0;
wire expected_last = (data_offset == 7) ||
