wire [15:0] expected_original = lengths_q[hr];
wire [15:0] expected_length = expected_original < 4 ? 16'd4 : (expected_original > 8 ? 16'd8 : expected_original);
wire final_tail = enabled && !rst && !s_valid && m_ready && h_ready && tail_count >= 128;

assign active[0] = (seen && reset_edge) || final_tail;
assign ok[0] = (!reset_edge || (!m_valid && !h_valid)) &&
